// === Tab: mySketch ===
let sh;
let lapse = 0;    // mouse timer

let Pallets = [
	createCols("https://coolors.co/cbdfd1-6e9893-fffcda-5a362b"),
	createCols("https://coolors.co/dee7e5-abc4c2-baf7c7-3b5a2b"),
	createCols("https://coolors.co/b4f8bc-9e83ec-fffa75-d14333")
]

function setup() {
	createCanvas(1112, 834,WEBGL);

	//shader
	sh = createShader(vert,frag);
	this.shader(sh);
	sh.setUniform("u_resolution", [width*pixelDensity(),height*pixelDensity()]);
	let scale = random(7,15);
	let seaLine = random(0.2,0.5);
	sh.setUniform("scale", scale);
	sh.setUniform("offset", [random(200),random(200)]);
	sh.setUniform("seaLine",seaLine);
	let cols = Pallets[int(random(Pallets.length))];
	setCol(cols[0],sh,"seaCol_1");
	setCol(cols[1],sh,"seaCol_2");
	setCol(cols[2],sh,"landCol_1");
	setCol(cols[3],sh,"landCol_2");

	noStroke();	
	noLoop();
}

function draw() {
	sh.setUniform("u_time", millis()/1000);
	rect(-width/2,-height/2,width,height);
}


function createCols(_url)
{
  let slash_index = _url.lastIndexOf('/');
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split('-');
  for (let i = 0; i < arr.length; i++) {
    arr[i] = '#' + arr[i];
  }
  return arr;
}

//_col  color or number
function setCol(_col,_shader = sh,_uniformName = "u_col")
{
	const col = typeof (_col) == "string" ? color(_col) : _col;
	let　colArray = col._array;
	colArray.pop();
	_shader.setUniform(_uniformName,colArray);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
} 

