var vert = `
		precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;


var frag = `

precision highp float;
#define PI 3.14159265359


uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

uniform vec3 seaCol_1;
uniform vec3 seaCol_2;
uniform vec3 landCol_1;
uniform vec3 landCol_2;
uniform float scale;
uniform float seaLine;
uniform vec2 offset;
float stepNum = 100.0/scale;
float ountLineM = 4.0;


//util
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }


//noise
float random (in vec2 st) {
   	highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(st.xy ,vec2(a,b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

float noise(vec2 st) {
    vec2 i = vec2(0.);
		i = floor(st);
    vec2 f = vec2(0.);
		f = fract(st);
    vec2 u =  vec2(0.);
		u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}


float snoise(vec2 v) {
    const vec4 C = vec4(0.211324865405187,
                        // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,
                        // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,
                        // -1.0 + 2.0 * C.x
                        0.024390243902439);
                        // 1.0 / 41.0

    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);

    vec2 i1 = vec2(0.0);
    i1 = (x0.x > x0.y)? vec2(1.0, 0.0):vec2(0.0, 1.0);
    vec2 x1 = x0.xy + C.xx - i1;
    vec2 x2 = x0.xy + C.zz;

    i = mod289(i);
    vec3 p = permute(
            permute( i.y + vec3(0.0, i1.y, 1.0))
                + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(
                        dot(x0,x0),
                        dot(x1,x1),
                        dot(x2,x2)
                        ), 0.0);

    m = m*m ;
    m = m*m ;

    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;

    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0+h*h);

    // Compute final noise value at P
    vec3 g = vec3(0.0);
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * vec2(x1.x,x2.x) + h.yz * vec2(x1.y,x2.y);
    return 130.0 * dot(m, g);
}

#define RIDGEOCTAVES 3
// Ridged multifractal
float ridge(float h, float offset) {
    h = abs(h);     // create creases
    h = offset - h; // invert so creases are at top
    h = h * h;      // sharpen creases
    return h;
}

float ridgedMF(vec2 p) {
    float lacunarity = 2.0;
    float gain = 0.5;
    float offset = 0.9;

    float sum = 0.0;
    float freq = 1.0, amp = 0.5;
    float prev = 1.0;
    for(int i=0; i < RIDGEOCTAVES; i++) {
        float n = ridge(snoise(p*freq), offset);
        sum += n*amp;
        sum += n*amp*prev;  // scale by previous octave
        prev = n;
        freq *= lacunarity;
        amp *= gain;
    }
    return sum;
}


#define OCTAVES 6
float fbm (in vec2 st) {
    // Initial values
    float value = 0.0;
    float amplitude = .5;
    float frequency = 0.;
    //
    // Loop of octaves
    for (int i = 0; i < OCTAVES; i++) {
        value += amplitude * noise(st);
        st *= 2.;
        amplitude *= .5;
    }
    return value;
}

//count
float timeRatio(float time, float cycle){
    float timeRatio = mod(time, cycle) / cycle;
    return timeRatio;
}

float timeRadius(float time, float cycle){
    return timeRatio(time, cycle)*PI*2.0;
}


float grid(vec2 uv, float num)
{
    float w = scale/u_resolution.x*1.5 ;
    uv *= num;
    uv = fract(uv);
    float v = uv.x >= 0.5 && uv.x < 0.5+w || uv.y >= 0.5 && uv.y < 0.5+w ? 1. : 0.;
    return v;
}

void main() {
   	vec2 pos = gl_FragCoord.xy/u_resolution.x;
    pos += vec2(u_time/u_resolution.x * 100.0,0.0) + offset;
    pos += noise(pos * u_resolution/10.0) * 0.001;

    //baseCol
    float landNoise = fbm(pos*scale);
    float landNoiseRight = fbm(pos*scale + vec2(scale/u_resolution.x, 0.0));
    float landNoiseDown = fbm(pos*scale + vec2(0.0, scale/u_resolution.y));
    float landTone =  floor(landNoise* stepNum);
    vec3 baseCol = landTone < stepNum *seaLine ? mix(seaCol_2, seaCol_1, landTone / (stepNum * seaLine)) :  mix(landCol_1, landCol_2, (landTone - stepNum * seaLine) / (stepNum * (1.0-seaLine - 0.2)));

    //line
    landTone =  floor(landNoise* stepNum * ountLineM);
    float landToneRight =  floor(landNoiseRight* stepNum * ountLineM);
    float landToneDown =  floor(landNoiseDown* stepNum * ountLineM);
    float outline = max(abs(landTone-landToneRight) , abs(landTone - landToneDown)) * clamp(noise(pos) + 0.7, 0.0, 1.0);

    //mount
    float mount = ridgedMF(pos * scale* 3.5) * landNoise * landNoise;
    mount = landNoise > 0.3 ? smoothstep(0.0,0.9,mount) : 0.0;

    //combine
    vec3 col = baseCol;
    col = mount * (landCol_2+0.5) * col + (1.0 - mount) * col;
    col = col * (1.0 - outline) + (col - 0.2) * outline;
   	col -= grid(pos,20.0)*0.2;
    col -= grid(pos,100.0)*0.2;
    col = random(pos)*(col +0.1) + (1.0 - random(pos))* col;

    gl_FragColor = vec4(vec3(col), 1.0);
}



`;

